
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_optb88_vdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_optb88_vdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.292312752323531e+00, -4.210159164577638e+00, -4.095115078341572e+00, -3.935902842305821e+00, -3.719274936383333e+00, -3.431626770871897e+00, -3.062779459418407e+00, -2.612745733083851e+00, -2.100646964075192e+00, -1.568627756077034e+00, -1.061313450935184e+00, -7.045036172764446e-01, -6.013395999647592e-01, -4.980009437611755e-01, -3.637424151296199e-01, -2.370773990088332e-01, -1.441905488044877e-01, -8.603693360417962e-02, -5.322237339942242e-02, -3.594669988494167e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


